<script setup>
import { ref, onMounted, computed } from 'vue';
import { db } from './db.js';
import * as XLSX from 'xlsx';

// Стан програми
const activeTab = ref('sklad'); // sklad, log, stat, excel
const inventory = ref([]);
const transactions = ref([]);
const message = ref('');

// Списки для швидкого вибору (без вводу тексту)
const itemCategories = ['Дрони', 'Батареї', 'Спарки', 'Інше'];
const commonItems = ['Mavic 3', 'Mavic 3T', 'Mavic 4', 'Matrice 30T', 'Matrice 300', 'Autel Max', 'Батарея M3', 'Спарка'];

// Форми
const formItem = ref(commonItems[0]);
const formCategory = ref(itemCategories[0]);
const formQty = ref(1);
const formType = ref('Втрата'); // Втрата, Прихід

// Фільтри статистики
const statStart = ref(new Date(new Date().setDate(1)).toISOString().split('T')[0]); // 1-ше число поточного місяця
const statEnd = ref(new Date().toISOString().split('T')[0]); // сьогодні

// Завантаження даних
const loadData = async () => {
  inventory.value = await db.inventory.toArray();
    transactions.value = await db.transactions.orderBy('date').reverse().toArray();
    };

    onMounted(loadData);

    // Показувач повідомлень
    const showMsg = (text, isError = false) => {
      message.value = (isError ? '❌ ' : '✅ ') + text;
        setTimeout(() => message.value = '', 3000);
        };

        // Додавання/списання майна
        const processTransaction = async () => {
          try {
              // 1. Шукаємо, чи є вже такий товар на складі
                  let item = await db.inventory.where('name').equals(formItem.value).first();
                      
                          let newQty = formQty.value;
                              if (item) {
                                    newQty = formType.value === 'Втрата' ? item.quantity - formQty.value : item.quantity + formQty.value;
                                          if (newQty < 0) newQty = 0; // Запобігаємо мінусам
                                                await db.inventory.update(item.id, { quantity: newQty });
                                                    } else {
                                                          // Якщо товару ще не було, але ми робимо "Втрату", це помилка обліку, але пропустимо і створимо з 0
                                                                newQty = formType.value === 'Втрата' ? 0 : formQty.value;
                                                                      await db.inventory.add({ name: formItem.value, category: formCategory.value, quantity: newQty });
                                                                          }

                                                                              // 2. Записуємо історію руху
                                                                                  await db.transactions.add({
                                                                                        date: new Date().toISOString(),
                                                                                              name: formItem.value,
                                                                                                    type: formType.value,
                                                                                                          quantity: formQty.value
                                                                                                              });

                                                                                                                  await loadData();
                                                                                                                      showMsg('Запис додано успішно!');
                                                                                                                          formQty.value = 1;
                                                                                                                            } catch (error) {
                                                                                                                                showMsg('Помилка бази даних!', true);
                                                                                                                                  }
                                                                                                                                  };

                                                                                                                                  // --- АНАЛІТИКА ---
                                                                                                                                  const statResults = computed(() => {
                                                                                                                                    const start = new Date(statStart.value);
                                                                                                                                      start.setHours(0, 0, 0, 0);
                                                                                                                                        const end = new Date(statEnd.value);
                                                                                                                                          end.setHours(23, 59, 59, 999);

                                                                                                                                            // Рахуємо кількість днів у періоді
                                                                                                                                              const daysDiff = Math.round((end - start) / (1000 * 6000 * 24)) || 1; 
                                                                                                                                                // 1000 * 3600 * 24 (виправлено нижче у виводі)
                                                                                                                                                  const days = Math.max(1, Math.ceil((end - start) / (1000 * 3600 * 24)));

                                                                                                                                                    // Фільтруємо втрати за період
                                                                                                                                                      const losses = transactions.value.filter(t => 
                                                                                                                                                          t.type === 'Втрата' && 
                                                                                                                                                              new Date(t.date) >= start && 
                                                                                                                                                                  new Date(t.date) <= end
                                                                                                                                                                    );

                                                                                                                                                                      // Групуємо втрати по назвах
                                                                                                                                                                        const grouped = {};
                                                                                                                                                                          losses.forEach(t => {
                                                                                                                                                                              if (!grouped[t.name]) grouped[t.name] = 0;
                                                                                                                                                                                  grouped[t.name] += t.quantity;
                                                                                                                                                                                    });

                                                                                                                                                                                      // Формуємо масив результатів з середнім значенням
                                                                                                                                                                                        return Object.keys(grouped).map(name => ({
                                                                                                                                                                                            name,
                                                                                                                                                                                                totalLost: grouped[name],
                                                                                                                                                                                                    avgPerDay: (grouped[name] / days).toFixed(2)
                                                                                                                                                                                                      }));
                                                                                                                                                                                                      });

                                                                                                                                                                                                      // --- EXCEL ЕКСПОРТ ---
                                                                                                                                                                                                      const exportExcel = () => {
                                                                                                                                                                                                        try {
                                                                                                                                                                                                            const wb = XLSX.utils.book_new();
                                                                                                                                                                                                                
                                                                                                                                                                                                                    // Аркуш 1: Залишки
                                                                                                                                                                                                                        const wsInventory = XLSX.utils.json_to_sheet(inventory.value.map(i => ({
                                                                                                                                                                                                                              'Категорія': i.category,
                                                                                                                                                                                                                                    'Назва': i.name,
                                                                                                                                                                                                                                          'Кількість на складі': i.quantity
                                                                                                                                                                                                                                              })));
                                                                                                                                                                                                                                                  XLSX.utils.book_append_sheet(wb, wsInventory, 'Залишки');

                                                                                                                                                                                                                                                      // Аркуш 2: Історія
                                                                                                                                                                                                                                                          const wsLogs = XLSX.utils.json_to_sheet(transactions.value.map(t => ({
                                                                                                                                                                                                                                                                'Дата': new Date(t.date).toLocaleString('uk-UA'),
                                                                                                                                                                                                                                                                      'Майно': t.name,
                                                                                                                                                                                                                                                                            'Операція': t.type,
                                                                                                                                                                                                                                                                                  'Кількість': t.quantity
                                                                                                                                                                                                                                                                                      })));
                                                                                                                                                                                                                                                                                          XLSX.utils.book_append_sheet(wb, wsLogs, 'Журнал рухів');

                                                                                                                                                                                                                                                                                              XLSX.writeFile(wb, `Звіт_Склад_${new Date().toLocaleDateString('uk-UA')}.xlsx`);
                                                                                                                                                                                                                                                                                                  showMsg('Файл Excel завантажено!');
                                                                                                                                                                                                                                                                                                    } catch (error) {
                                                                                                                                                                                                                                                                                                        showMsg('Помилка генерації Excel!', true);
                                                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                                                          };

                                                                                                                                                                                                                                                                                                          // --- EXCEL ІМПОРТ ---
                                                                                                                                                                                                                                                                                                          const importExcel = (event) => {
                                                                                                                                                                                                                                                                                                            const file = event.target.files[0];
                                                                                                                                                                                                                                                                                                              if (!file) return;

                                                                                                                                                                                                                                                                                                                const reader = new FileReader();
                                                                                                                                                                                                                                                                                                                  reader.onload = async (e) => {
                                                                                                                                                                                                                                                                                                                      try {
                                                                                                                                                                                                                                                                                                                            const data = new Uint8Array(e.target.result);
                                                                                                                                                                                                                                                                                                                                  const wb = XLSX.read(data, { type: 'array' });
                                                                                                                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                                                                                                                              // Зчитуємо залишки
                                                                                                                                                                                                                                                                                                                                                    const invSheet = wb.Sheets['Залишки'];
                                                                                                                                                                                                                                                                                                                                                          if (invSheet) {
                                                                                                                                                                                                                                                                                                                                                                  const invData = XLSX.utils.sheet_to_json(invSheet);
                                                                                                                                                                                                                                                                                                                                                                          await db.inventory.clear(); // Очищаємо стару базу перед імпортом
                                                                                                                                                                                                                                                                                                                                                                                  for (const row of invData) {
                                                                                                                                                                                                                                                                                                                                                                                            await db.inventory.add({
                                                                                                                                                                                                                                                                                                                                                                                                        category: row['Категорія'] || 'Інше',
                                                                                                                                                                                                                                                                                                                                                                                                                    name: row['Назва'],
                                                                                                                                                                                                                                                                                                                                                                                                                                quantity: Number(row['Кількість на складі']) || 0
                                                                                                                                                                                                                                                                                                                                                                                                                                          });
                                                                                                                                                                                                                                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                              await loadData();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    showMsg('Дані з Excel успішно завантажено!');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                          event.target.value = ''; // Скидаємо інпут
                                                                                                                                                                                                                                                                                                                                                                                                                                                                              } catch (error) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    showMsg('Помилка читання файлу! Перевірте формат.', true);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            reader.readAsArrayBuffer(file);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </script>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <template>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <div class="max-w-md mx-auto bg-gray-50 min-h-screen shadow-lg pb-20">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <!-- Шапка -->
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <header class="bg-slate-800 text-white p-4 font-bold text-center text-xl shadow-md">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            📦 Склад БПЛА
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </header>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <!-- Повідомлення -->
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <div v-if="message" class="fixed top-4 left-1/2 -translate-x-1/2 bg-gray-900 text-white px-6 py-3 rounded-full font-bold shadow-2xl z-50 transition-all">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              {{ message }}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <!-- Вміст вкладок -->
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <div class="p-4 space-y-4">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <!-- ВКЛАДКА: СКЛАД -->
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <div v-if="activeTab === 'sklad'">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <h2 class="text-xl font-bold text-gray-800 mb-4">Поточні залишки</h2>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <div v-if="inventory.length === 0" class="text-center text-gray-500 py-10 font-medium">Склад порожній. Додайте майно через вкладку "Рух".</div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <div v-for="item in inventory" :key="item.id" class="bg-white p-4 rounded-xl shadow-sm mb-3 flex justify-between items-center border-l-4" :class="item.quantity > 0 ? 'border-green-500' : 'border-red-500'">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <div class="text-xs text-gray-500 font-bold uppercase">{{ item.category }}</div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <div class="text-lg font-black text-gray-800">{{ item.name }}</div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <div class="text-3xl font-black" :class="item.quantity > 0 ? 'text-green-600' : 'text-red-600'">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      {{ item.quantity }} <span class="text-sm font-normal text-gray-500">шт</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <!-- ВКЛАДКА: РУХ -->
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <div v-if="activeTab === 'log'" class="bg-white p-5 rounded-2xl shadow-sm">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <h2 class="text-xl font-bold text-gray-800 mb-4">Запис руху майна</h2>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <label class="block text-sm font-bold text-gray-600 mb-1">Що записуємо?</label>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <select v-model="formItem" class="w-full bg-gray-100 rounded-xl p-3 text-lg font-bold mb-4 outline-none">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <option v-for="item in commonItems" :key="item" :value="item">{{ item }}</option>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </select>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <label class="block text-sm font-bold text-gray-600 mb-1">Категорія (для нових)</label>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <select v-model="formCategory" class="w-full bg-gray-100 rounded-xl p-3 text-lg font-bold mb-4 outline-none">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <option v-for="cat in itemCategories" :key="cat" :value="cat">{{ cat }}</option>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </select>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <label class="block text-sm font-bold text-gray-600 mb-1">Кількість</label>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <div class="flex items-center gap-4 mb-6">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <button @click="formQty > 1 && formQty--" class="flex-1 bg-gray-200 text-gray-700 rounded-xl text-3xl font-black py-2 active:bg-gray-300">-</button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <div class="text-4xl font-black text-gray-800 w-16 text-center">{{ formQty }}</div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <button @click="formQty++" class="flex-1 bg-gray-200 text-gray-700 rounded-xl text-3xl font-black py-2 active:bg-gray-300">+</button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <div class="flex gap-2">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <button @click="formType = 'Втрата'; processTransaction()" class="flex-1 bg-red-500 hover:bg-red-600 active:bg-red-700 text-white font-black py-4 rounded-xl text-lg shadow-lg">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ВТРАТА / СПИСАНО
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <button @click="formType = 'Прихід'; processTransaction()" class="flex-1 bg-green-500 hover:bg-green-600 active:bg-green-700 text-white font-black py-4 rounded-xl text-lg shadow-lg">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ПРИХІД / ДОДАНО
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <!-- ВКЛАДКА: АНАЛІТИКА -->
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <div v-if="activeTab === 'stat'">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <h2 class="text-xl font-bold text-gray-800 mb-4">Статистика втрат</h2>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <div class="bg-white p-4 rounded-xl shadow-sm mb-4">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <label class="block text-sm font-bold text-gray-600 mb-1">Діапазон дат</label>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <div class="flex gap-2">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <input v-model="statStart" type="date" class="flex-1 bg-gray-100 p-2 rounded-lg font-bold outline-none text-sm" />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <input v-model="statEnd" type="date" class="flex-1 bg-gray-100 p-2 rounded-lg font-bold outline-none text-sm" />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <div v-if="statResults.length === 0" class="text-center text-gray-500 py-6">За обраний період втрат не зафіксовано.</div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <div v-for="res in statResults" :key="res.name" class="bg-white p-4 rounded-xl shadow-sm mb-3 border-l-4 border-slate-700">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <div class="text-lg font-black text-gray-800 mb-2">{{ res.name }}</div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <div class="flex justify-between">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <div class="text-center bg-red-100 text-red-700 px-3 py-2 rounded-lg flex-1 mr-2">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <div class="text-xs font-bold">Всього втрат</div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <div class="text-2xl font-black">{{ res.totalLost }}</div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <div class="text-center bg-blue-100 text-blue-700 px-3 py-2 rounded-lg flex-1 ml-2">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <div class="text-xs font-bold">Втрат на день</div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <div class="text-2xl font-black">{{ res.avgPerDay }}</div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <!-- ВКЛАДКА: EXCEL -->
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <div v-if="activeTab === 'excel'" class="bg-white p-5 rounded-2xl shadow-sm space-y-6">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <h2 class="text-xl font-bold text-gray-800 mb-2">Експорт бази</h2>
